    body: "今天最后一段练习曲停住，房间里只剩轻轻的回声。小猪把一颗小糖收进枕头边，说留着明天尝。小金毛用耳朵轻轻碰碰她的手指，软乎乎的。把小事一件件做完，心里也跟着轻快起来。指尖触到织物，是软的、厚的、让人想闭眼的那种。两个人互相让着一点位置，谁也不挤谁。想起白天某个小小的笑，嘴角也松了下来。她翻了个身，被子顺着姿势回到肩上，不用自己去拉。呼吸慢下来，今天就圆满地收好了。"
