    body: "闷了一整天，这会儿终于能靠着垫子喘口气。小猪摊开肚皮歇着，偶尔抬眼看她一下。小金毛把暖暖的侧脸贴过来，给她当一个小靠垫。两个人不需要很多话，待在一起就觉得踏实。空气里是洗衣液淡淡的清香，混着一点晒过的味道。她轻轻舒了口气，像是把胸口那块小石头放下了。两个人互相让着一点位置，谁也不挤谁。耳边的声音越来越远，只剩身边温热的陪伴。就这样安心地歇着，明天的事交给明天。"
