    body: "晚风把窗帘掀起又放下，像在轻轻招手。小猪把掉下来的绒线团推回篮子里，不想乱了地方。小金毛把她留在沙发上的围巾叼来，搭到扶手上。她的呼吸慢慢变匀，身边的陪伴是结实的。指尖触到织物，是软的、厚的、让人想闭眼的那种。想起白天某个小小的笑，嘴角也松了下来。眼皮有点沉，她顺从地把眼睛闭上一会儿。她轻轻舒了口气，像是把胸口那块小石头放下了。睡吧，今晚什么都不用多想，梦里也是软软的。"
