    body: "抱着靠垫坐了一会儿，整个人慢慢放松下来。小猪陪着她不说话，只是贴着待在一旁。小金毛把脑袋钻到她手臂弯里，先占好暖和的位置。一句轻轻的“辛苦了”，让肩膀卸下一点重量。窗外树影晃动，投在墙上是柔柔的几片暗色。耳边的声音越来越远，只剩身边温热的陪伴。一小片安静落下来，把今天的烦心事挡在了外面。她轻轻舒了口气，像是把胸口那块小石头放下了。就这样安心地歇着，明天的事交给明天。"
