    body: "床头的小灯调到最暗，屋里是暖融融的橘色。小猪把一颗小糖收进枕头边，说留着明天尝。小金毛叼来一颗自己最喜欢的零食，放在她旁边表示分担。两个人不需要很多话，待在一起就觉得踏实。屋里的温度一点点爬升，困意也跟着上来。枕头被拍了两下，软乎乎地陷下去，刚好托住脖子。眼皮有点沉，她顺从地把眼睛闭上一会儿。想起白天某个小小的笑，嘴角也松了下来。月光守在窗外，身边守着他们，谁也不会打扰。"
